#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int MAXN = (1 << 20) + 5;

int n, fullMask, total;
int dp1[MAXN], dp2[MAXN];
int flag[10][10], grid[10][10], tripleIdx[10][10][10];

long long modExp(long long base, long long exp) {
    long long result = 1;
    while (exp) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

long long modInv(long long x) {
    return modExp(x, MOD - 2);
}

bool satisfies(int a, int b, int c) {
    int nums[3] = {a, b, c};
    int order[3] = {0, 1, 2};
    do {
        if (flag[nums[order[0]]][1] && 
            flag[nums[order[1]]][2] && 
            flag[nums[order[2]]][3]) {
            return true;
        }
    } while (next_permutation(order, order + 3));
    return false;
}

void traverse1(int coef, int row, int col) {
    if (row == 7 && col == 1) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (satisfies(i, j, k)) {
                        int x = 1;
                        while (x == i || x == j || x == k) ++x;
                        int y = x + 1;
                        while (y == i || y == j || y == k) ++y;
                        int z = y + 1;
                        while (z == i || z == j || z == k) ++z;
                        state |= tripleIdx[x][y][z];
                    }
        dp1[state] = (dp1[state] + coef) % MOD;
        return;
    }

    flag[row][col] = 1;
    if (col == 3) traverse1(1LL * coef * grid[row][col] % MOD, row + 1, 1);
    else traverse1(1LL * coef * grid[row][col] % MOD, row, col + 1);
    flag[row][col] = 0;

    if (col == 3) traverse1(1LL * coef * (MOD + 1 - grid[row][col]) % MOD, row + 1, 1);
    else traverse1(1LL * coef * (MOD + 1 - grid[row][col]) % MOD, row, col + 1);
}

void traverse2(int coef, int row, int col) {
    if (row == 7 && col == 4) {
        int state = 0;
        for (int i = 1; i <= 6; ++i)
            for (int j = i + 1; j <= 6; ++j)
                for (int k = j + 1; k <= 6; ++k)
                    if (satisfies(i, j, k)) state |= tripleIdx[i][j][k];
        dp2[state] = (dp2[state] + coef) % MOD;
        total = (total + 1LL * dp1[fullMask ^ state] * coef) % MOD;
        return;
    }

    flag[row][col - 3] = 1;
    if (col == 6) traverse2(1LL * coef * grid[row][col] % MOD, row + 1, 4);
    else traverse2(1LL * coef * grid[row][col] % MOD, row, col + 1);
    flag[row][col - 3] = 0;

    if (col == 6) traverse2(1LL * coef * (MOD + 1 - grid[row][col]) % MOD, row + 1, 4);
    else traverse2(1LL * coef * (MOD + 1 - grid[row][col]) % MOD, row, col + 1);
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= n; ++j) {
            int temp;
            scanf("%d", &temp);
            grid[i][j] = 1LL * temp * modInv(100) % MOD;
        }
    for (int i = n + 1; i <= 6; ++i) grid[i][i] = 1;

    int idx = 0;
    for (int i = 1; i <= 6; ++i)
        for (int j = i + 1; j <= 6; ++j)
            for (int k = j + 1; k <= 6; ++k)
                tripleIdx[i][j][k] = 1 << idx++;

    traverse1(1, 1, 1);
    fullMask = (1 << 20) - 1;

    for (int bit = 0; bit < 20; ++bit)
        for (int state = 0; state <= fullMask; ++state)
            if (state >> bit & 1)
                dp1[state] = (dp1[state] + dp1[state ^ (1 << bit)]) % MOD;

    traverse2(1, 1, 4);
    total = (MOD + 1 - total) % MOD;
    printf("%d\n", total);
    return 0;
}
